SELECT t.*, (select a.bank_account_name from csh_bank_account a where a.bank_account_id = t.bank_account_id)bank_account_name, (select a.bank_account_num from csh_bank_account a where a.bank_account_id = t.bank_account_id) bank_account_num, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=t.PAYMENT_METHOD and scb.CODE='CSH.PAYMENT_METHOD') as payment_method_n FROM csh_transaction_refund_ln t
AND t.refund_id = #{refundId}
order by t.ln_id

SELECT t1.* FROM (SELECT ct.TRANSACTION_ID, ct.TRANSACTION_NUM, ct.TRANSACTION_TYPE, ct.posted_flag, cc.CONTRACT_ID, cc.contract_number, ctrl.ln_id, ctrl.refund_id, ctrl.bank_account_id, ctrl.refund_amount, ctrl.payment_method, ctrl.bank_slip_num, ctrl.object_version_number, ctrl.request_id, ctrl.program_id, ctrl.created_by, ctrl.creation_date, ctrl.last_updated_by, ctrl.last_update_date, ctrl.last_update_login, ctrl.SOURCE_TRANSACTION_ID, ct.TRANSACTION_DATE, ct.TRANSACTION_AMOUNT, ct.CURRENCY_CODE, nvl(ct.WRITE_OFF_AMOUNT, 0) AS WRITE_OFF_AMOUNT, (SELECT m.BP_NAME FROM HLS_BP_MASTER m WHERE m.BP_ID = ct.BP_ID) AS bp_payment_name, (SELECT scvb.MEANING FROM SYS_CODE_B scb LEFT JOIN SYS_CODE_VALUE_B scvb ON scb.CODE = 'CSH301_TRANSACTION_TYPE' AND scb.CODE_ID = scvb.CODE_ID WHERE scvb.VALUE = ct.TRANSACTION_TYPE) AS transaction_type_desc, (SELECT scvb.MEANING FROM SYS_CODE_B scb LEFT JOIN SYS_CODE_VALUE_B scvb ON scb.CODE = 'CHS.CURRENCY_TYPE' AND scb.CODE_ID = scvb.CODE_ID WHERE scvb.VALUE = ct.CURRENCY_CODE) AS currency_code_desc, (SELECT nvl(SUM(cwo.csh_write_off_amount), 0) FROM csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id AND cwo.reversed_flag = 'N' AND cwo.write_off_type = 'REFUND') return_write_off_amount, (nvl(ct.transaction_amount, 0) - nvl(ct.block_amount, 0) - (SELECT nvl(SUM(cwo.csh_write_off_amount), 0) FROM csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id AND cwo.reversed_flag = 'N')) AS can_return_amount FROM csh_transaction_refund_ln ctrl INNER JOIN csh_transaction ct ON ct.TRANSACTION_ID = ctrl.SOURCE_TRANSACTION_ID LEFT JOIN con_contract cc ON ct.contract_id = cc.contract_id WHERE ct.TRANSACTION_TYPE IN ('ADVANCE_RECEIPT', 'DEPOSIT', 'MANAGEMENT_FEE', 'PERFORMANCE_BOND')) t1
and t1.refund_id = #{refundId}
AND t1.transaction_id in
